BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷112·太祖本纪三·广顺三年二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0712155a855a3f88decd328f54992920391e363e/content/books/zizhi-tongjian/vol-291/year-0953/part-02/sources/library/jiuwudaishi-112-february-953/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺三年二月，段落 jiu-wudaishi-205deb4a7860-p002683；已核上下文及传主，纸本及异文待核。", "id": "e0b012a3-33cd-565e-9057-b44b83d81dc4"}, {"title": "旧五代史·卷130·王峻传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0712155a855a3f88decd328f54992920391e363e/content/books/zizhi-tongjian/vol-291/year-0953/part-02/sources/library/jiuwudaishi-130-wangjun-dismissal/source.txt", "note": "《旧五代史》卷130·王峻传，段落 jiu-wudaishi-205deb4a7860-p003052；已核上下文及传主，纸本及异文待核。", "id": "6dea5a8c-eb44-59dc-a461-706866660f90"}, {"title": "资治通鉴·卷291·广顺三年二月至五月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0712155a855a3f88decd328f54992920391e363e/content/books/zizhi-tongjian/vol-291/year-0953/part-02/sources/library/tongjian-291-953-february-march/source.txt", "note": "《资治通鉴》卷291·广顺三年二月至五月，段落 zizhi-tongjian-a63549944a71-p003457；已核上下文及传主，纸本及异文待核。", "id": "860558e2-1135-5a40-84b3-c70f490d2797"}, {"title": "资治通鉴·卷291·广顺三年湖南将领冲突回述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0712155a855a3f88decd328f54992920391e363e/content/books/zizhi-tongjian/vol-291/year-0953/part-02/sources/library/tongjian-291-953-hunan-conflict/source.txt", "note": "《资治通鉴》卷291·广顺三年湖南将领冲突回述，段落 zizhi-tongjian-a63549944a71-p003456；已核上下文及传主，纸本及异文待核。", "id": "7aa4dcf8-35ea-5897-b65a-086469e151dd"}, {"title": "新五代史·卷50·杂传第三十八·王峻", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0712155a855a3f88decd328f54992920391e363e/content/books/zizhi-tongjian/vol-291/year-0953/part-02/sources/library/xinwudaishi-50-wangjun-dismissal/source.txt", "note": "《新五代史》卷50·杂传第三十八·王峻，段落 xin-wudaishi-b08f244b9241-p001937；已核上下文及传主，纸本及异文待核。", "id": "dd1bb2f2-d55f-57f4-b72b-56644afe1ac6"}, {"title": "新五代史·卷66·楚世家第六·刘言", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0712155a855a3f88decd328f54992920391e363e/content/books/zizhi-tongjian/vol-291/year-0953/part-02/sources/library/xinwudaishi-66-he-zhu-killed/source.txt", "note": "《新五代史》卷66·楚世家第六·刘言，段落 xin-wudaishi-b08f244b9241-p003337；已核上下文及传主，纸本及异文待核。", "id": "484e7b25-2340-55e8-a054-33bb2cc42e4b"}, {"title": "资治通鉴·卷291·广顺三年正月至闰正月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/14cbc2e919886dae0472b77f2330611d8b32c8d7/content/books/zizhi-tongjian/vol-291/year-0953/part-01/sources/library/tongjian-291-953-january-intercalary/source.txt", "note": "《资治通鉴》卷291·广顺三年正月至闰正月，段落 zizhi-tongjian-a63549944a71-p003455；已核上下文及传主，纸本及异文待核。", "id": "07c464bb-e6ff-59c9-85b5-96bfdf715a66"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "折从远", "aliases": ["折從遠", "折从阮", "折從阮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，府州刺史。后晋割让北地后，府州归属契丹。他据险抵制契丹迁民，后奉石重贵命令攻入契丹境内、拔十余寨，944年六月戊午任府州团练使。《新五代史》明确其后因避汉高祖名改称折从阮，字可久。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "500d7480-2e3a-5553-9370-8e4295db3cc1"}, {"name": "邵棠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：邵棠。", "biography": null, "status": "draft", "id": "27b9198c-4f63-5498-b713-96f92c483192"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "何敬真", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武陵人，朗州步军指挥使。950年率部族兵攻破韩礼在杨柳桥的防线；马希萼入长沙后任他为朗州牙内都指挥使，率兵戍守。生卒年未载。", "biography": null, "status": "draft", "id": "0ce9ccfa-b68b-575c-96b0-8022528be7ad"}, {"name": "朱全琇", "aliases": ["硃全琇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州牙将。952年与王逵等受刘言任命为指挥使，姓名底本写硃全琇。生卒年未载。", "biography": null, "status": "draft", "id": "88df4471-92c7-542f-b91b-ec31a9110353"}, {"name": "张文表", "aliases": ["張文表"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州人、刘言麾下牙将。952年任指挥使。史书称其善战，与周行逢、潘叔嗣交好、共同成事。生卒年未载。", "biography": null, "status": "draft", "id": "2a798366-dcd5-5e9c-a10a-a03e10aaa852"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "刘言", "aliases": ["劉言"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉州庐陵人，楚国辰州刺史。951年王逵、周行逢等欲迎他到朗州任副使，他单骑前往，众人废去马光惠后推他为权武平留后。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b32e335e-b386-5ab9-a996-bb31d55c6787"}, {"name": "李仲迁", "aliases": ["李仲遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州指挥使。所部三千人长期驻潭州，953年何敬真命其先赴岭北，部将符会等劫持他并擅自返回朗州。生卒年未载。", "biography": null, "status": "draft", "id": "3aab000b-4e23-53c1-ac0a-5bd605a8253b"}, {"name": "符会", "aliases": ["符會"], "era": "五代十国", "birth_year": null, "death_year": 953, "description": "李仲迁部下都头。953年利用士卒想归乡的情绪，劫持李仲迁擅自回朗州。后刘言在收到王逵诛杀何敬真的通知后处死符会等。生年未载。", "biography": null, "status": "draft", "id": "d196b0f7-7bf9-5a49-9af1-cf50d70a533f"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "颜衎", "aliases": ["顏衎"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋枢密直学士、工部郎中。939年废枢密院后，解除院内职务，保留本官。生卒年未载。", "biography": null, "status": "draft", "id": "b9f8cc2c-05c1-565a-a870-6fcd731c4ba9"}, {"name": "陈观", "aliases": ["陳觀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉给事中。947年十月刘知远亲征邺都时，派他入城向杜重威宣谕归降，杜重威闭门拒绝。生卒年未载。", "biography": null, "status": "draft", "id": "91fa9e7e-dc34-57a5-9199-5fe3f6f5ed8f"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "徐台符", "aliases": ["徐臺符"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武强人，后晋金部郎中、知制诰。944年六月戊辰任翰林学士。生卒年本段未载。", "biography": null, "status": "draft", "id": "28c5a951-7fb9-591a-b527-988ede5145c7"}, {"name": "蒋光远", "aliases": ["蔣光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周供奉官。《旧五代史》王峻传记953年受命押送被贬的王峻赴商州。生卒年未载。", "biography": null, "status": "draft", "id": "bc93dd34-880c-5c08-acf0-e093ce50a529"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}, {"name": "王承诲", "aliases": ["王承誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉后周将领王殷之子，任尚食使。953年王峻被贬后，郭威派他前往父亲所在的邺都，解释王峻获罪的情况。生卒年未载。", "biography": null, "status": "draft", "id": "5874077b-ab55-51ef-9d3d-790a135741bb"}, {"name": "高绍基", "aliases": ["高紹基"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "雄武节度使高允权之子、牙内指挥使。953年父死后图谋继任，隐瞒父丧，杀死劝谏的观察判官李彬并诬报谋反；朝廷派张仁谦巡检后才公开父丧。生卒年未载。", "biography": null, "status": "draft", "id": "e323db07-2f72-541e-ac62-3a221bd23837"}, {"name": "张怀贞", "aliases": ["張懷貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周供奉官。953年奉命率禁军两指挥驻鄜州、延州，以控制高绍基所在军府。生卒年未载。", "biography": null, "status": "draft", "id": "5ac117ff-8036-5128-b403-65be3fb2a61f"}, {"name": "张匡图", "aliases": ["張匡圖", "张图", "張圖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "雄武军副使。953年高绍基在朝廷调兵压力下把军府事务交给他。《旧五代史》同一交接记作张图，结合同日背景与副使身份保留别名，不与张图英混同。生卒年未载。", "biography": null, "status": "draft", "id": "288cc519-9d10-5b75-9f00-3462aa99fc9f"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "郑仁诲", "aliases": ["鄭仁誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，后周内客省使、恩州团练使。952年三月任枢密副使，新旧五代史同日记载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "f7eb66ac-1c5c-5720-aa2e-9256e75c2b71"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

